//! Desktop entry point for FNF: Oxide Engine.
//!
//! Android uses the `android_main` entry generated by `#[bevy_main]` in
//! `src/lib.rs`; iOS builds this same binary through the Xcode "Build Rust
//! Code" phase.

#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

fn main() {
    fnf_oxide_engine::run();
}
